<style>
@import url('https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,500;1,700&family=Lora:ital,wght@0,500;0,600;0,700;1,600;1,700&display=swap');
