.xd323-call{display:grid;grid-template-columns:48px 1fr;column-gap:12px;align-items:center}.xd323-call>i{grid-row:span 2;color:var(--xd323-yellow);font-size:42px}.xd323-call span{font-weight:800;color:#e8f0e8}.xd323-call a{font-size:22px;font-weight:900;color:#fff}.xd323-shop-btn{height:58px;border-radius:999px;background:var(--xd323-green);display:inline-flex;align-items:center;gap:16px;padding:0 26px;font-weight:900}.xd323-menu-toggle{display:none;border:0;background:var(--xd323-green);color:#fff;width:44px;height:44px;border-radius:8px}
