.xd323-categories{background:#fff}.xd323-circle-track{display:grid;grid-auto-flow:column;grid-auto-columns:180px;gap:34px;overflow-x:auto;scroll-snap-type:x mandatory;justify-content:start}.xd323-circle-track a{text-align:center;scroll-snap-align:start}.xd323-circle-track span{width:166px;height:166px;border-radius:50%;background:#fafafa;display:grid;place-items:center;overflow:hidden;margin:0 auto 18px}.xd323-circle-track img{width:86%;height:86%;object-fit:contain}.xd323-circle-track strong{display:block;font-size:19px;line-height:1.25}
