.xd323-faq{background:#fff}.xd323-faq__grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:70px;align-items:center}.xd323-faq__grid>img{width:100%;height:760px;object-fit:cover;border-radius:22px 22px 220px 22px}.xd323-faq__grid>div>p:not(.xd323-kicker){font-size:22px;margin:22px 0 38px;color:#222}.xd323-faq__list{display:grid;gap:16px}.xd323-faq details{background:#fff;border-radius:12px;box-shadow:0 10px 28px rgba(8,63,33,.08);padding:0 26px}.xd323-faq summary{list-style:none;min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px;font-size:21px;font-weight:900;cursor:pointer}.xd323-faq summary::-webkit-details-marker{display:none}.xd323-faq details[open] summary i{transform:rotate(180deg)}.xd323-faq details p{margin:0;padding:0 0 24px;color:var(--xd323-muted);font-size:18px}
