.xd323-news{background:#fff}.xd323-news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:42px}.xd323-news-grid article div{position:relative}.xd323-news-grid img{width:100%;height:310px;object-fit:cover;border-radius:16px}.xd323-news-grid time{position:absolute;top:14px;left:14px;background:var(--xd323-green);color:#fff;border-radius:6px;padding:8px 18px;font-size:18px;font-weight:900}.xd323-news-grid p{display:inline-flex;gap:12px;align-items:center;margin:-28px 0 20px 18px;background:#fff;color:var(--xd323-green);border-radius:0 16px 0 0;padding:12px 22px;position:relative;z-index:1}.xd323-news-grid h3{font-size:25px;line-height:1.32;margin:0 0 28px}.xd323-news-grid .xd323-btn{min-height:52px}
