.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.xd323-page h1,.xd323-page h2,.xd323-page h3,.xd323-brand,.xd323-newsletter h2{font-family:var(--xd323-font-display);font-optical-sizing:auto}.xd323-page h1,.xd323-page h2{font-weight:700;letter-spacing:-.035em}.xd323-page h3{font-weight:600;letter-spacing:-.018em}.xd323-hero h1{line-height:1.12}.xd323-heading h2,.xd323-about h2,.xd323-stats h2,.xd323-faq h2{line-height:1.22}.xd323-kicker,.xd323-nav,.xd323-btn,.xd323-topbar,.xd323-call,.xd323-shop-btn,.xd323-actions,.xd323-newsletter button{font-family:var(--xd323-font-body);letter-spacing:-.01em}.xd323-kicker{font-weight:800}.xd323-nav{font-weight:700}.xd323-btn{font-weight:800}.xd323-motion-ready .xd323-reveal{opacity:0;filter:blur(2px);transform:translate3d(0,-38px,0);transition:opacity .72s cubic-bezier(.22,1,.36,1),transform .72s cubic-bezier(.22,1,.36,1),filter .72s ease;transition-delay:var(--xd323-delay,0ms);will-change:opacity,transform}.xd323-motion-ready .xd323-reveal.is-visible{opacity:1;filter:none;transform:none}
